INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist FireWire dasselbe wie USB?', 2, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Standards"}, {"text": "Ja", "correct": false, "because": "Verschiedene Technologien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt FireWire?', 3, '[{"text": "Hochgeschwindigkeits-Datenübertragung", "correct": true, "because": "Bis zu 800 Mbps"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht primär"}, {"text": "Netzwerkverwaltung", "correct": false, "because": "Kein Verwaltungsfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Versionen gibt es von FireWire?', 5, '[{"text": "FireWire 400", "correct": true, "because": "400 Mbps"}, {"text": "FireWire 800", "correct": true, "because": "800 Mbps"}, {"text": "FireWire 100", "correct": false, "because": "Keine Version"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FireWire ist ein IEEE 1394 Standard. b) Es ist nur für interne Geräte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Extern genutzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei FireWire?', 4, '[{"text": "Übertragungsrate", "correct": false, "because": "Leistungsmerkmal"}, {"text": "Anschlüsse", "correct": false, "because": "Verbindungstyp"}, {"text": "Papiergröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob FireWire Hot-Swapping unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "Plug-and-Play"}, {"text": "Nein", "correct": false, "because": "Unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte nutzen typischerweise FireWire?', 3, '[{"text": "Externe Festplatten", "correct": true, "because": "Hochgeschwindigkeit"}, {"text": "Monitore", "correct": false, "because": "HDMI/DisplayPort"}, {"text": "Tastaturen", "correct": false, "because": "USB üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet FireWire?', 5, '[{"text": "Hohe Datenrate", "correct": true, "because": "Bis 800 Mbps"}, {"text": "Stromversorgung", "correct": true, "because": "Bis 45 Watt"}, {"text": "Geringe Kapazität", "correct": false, "because": "Nicht zutreffend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) FireWire ist schneller als USB 2.0. b) Es ist heute Standard. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht mehr Standard"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für FireWire?', 4, '[{"text": "Kompatible Anschlüsse", "correct": false, "because": "Verbindung nötig"}, {"text": "Treiber", "correct": false, "because": "Systemunterstützung"}, {"text": "Papierhandbuch", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist FireWire 800 abwärtskompatibel?', 2, '[{"text": "Ja", "correct": true, "because": "Mit 400 kompatibel"}, {"text": "Nein", "correct": false, "because": "Kompatibilität gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anschlüsse gibt es für FireWire?', 4, '[{"text": "6-Pin", "correct": true, "because": "FireWire 400"}, {"text": "9-Pin", "correct": true, "because": "FireWire 800"}, {"text": "USB-C", "correct": false, "because": "Anderer Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass FireWire keine Stromversorgung bietet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Bis 45 Watt"}, {"text": "Ja", "correct": false, "because": "Stromversorgung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei FireWire?', 3, '[{"text": "Datenrate", "correct": true, "because": "Leistungsfaktor"}, {"text": "Papierdokumente", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Datenrate zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FireWire unterstützt Peer-to-Peer. b) Es ist heute weit verbreitet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wenig genutzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat FireWire?', 5, '[{"text": "Geringe Verbreitung", "correct": true, "because": "USB dominiert"}, {"text": "Hohe Kosten", "correct": true, "because": "Teurer als USB"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei FireWire unwichtig?', 3, '[{"text": "Übertragungsrate", "correct": false, "because": "Leistung"}, {"text": "Kompatibilität", "correct": false, "because": "Anschlüsse"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann FireWire bis zu 63 Geräte verbinden?', 3, '[{"text": "Ja", "correct": true, "because": "Daisy-Chain"}, {"text": "Nein", "correct": false, "because": "Unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob FireWire von Apple entwickelt wurde?', 2, '[{"text": "Ja", "correct": true, "because": "1980er-Jahre"}, {"text": "Nein", "correct": false, "because": "Apple initiiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für FireWire zentral?', 4, '[{"text": "Hochgeschwindigkeitsübertragung", "correct": true, "because": "Kernprinzip"}, {"text": "Physische Speicherung", "correct": false, "because": "Kein Speicher"}, {"text": "Papierdokumente", "correct": false, "because": "Irrelevant"}]');
